### app/app.js (4802 bytes)

```js
// Entry point: loads the trophy data, wires filters, tabs, checklist, detail, roadmap and
// missables together, keeps progress and the spoiler setting in localStorage, and drives
// the header progress bar and the shown-trophy counter.
import { loadEarned, saveEarned, loadSpoiler, saveSpoiler, exportProgress, importProgress } from './js/state.js';
import { filters, bindFilters, visibleTrophies } from './js/filters.js';
import { renderChecklist } from './js/checklist.js';
import { renderDetail } from './js/detail.js';
import { renderRoadmap } from './js/roadmap.js';
import { renderMissables } from './js/missables.js';

const TAB_ORDER = ['checklist', 'roadmap', 'missables', 'about'];
const TAB_KEY = 'gta6-last-tab';

const panes = {
  checklist: document.getElementById('checklist'),
  roadmap: document.getElementById('roadmap'),
  missables: document.getElementById('missables'),
  about: document.getElementById('about'),
};
const detail = document.getElementById('detail');
const progressfill = document.getElementById('progressfill');
const progress = document.getElementById('progress');
const showncount = document.getElementById('showncount');
const spoilerBox = document.getElementById('spoiler');

let doc;
try {
  doc = await (await fetch('data/trophies.json')).json();
  if (!Array.isArray(doc.trophies) || doc.trophies.length !== 55) {
    throw new Error('expected 55 trophies, got ' + (doc.trophies?.length ?? 0));
  }
} catch (err) {
  progress.textContent = 'Trophy data failed to load: ' + err.message;
  throw err;
}

let earned = loadEarned();
let selected = null;
let tab = TAB_ORDER.includes(sessionStorage.getItem(TAB_KEY)) ? sessionStorage.getItem(TAB_KEY) : 'checklist';

spoilerBox.checked = loadSpoiler();
filters.spoiler = spoilerBox.checked;

function updateProgress() {
  const pct = Math.round((earned.size / doc.trophies.length) * 100);
  progressfill.style.width = pct + '%';
  progress.textContent = earned.size + ' of ' + doc.trophies.length + ' earned · ' + pct + '%';
}

function currentTrophy() {
  return doc.trophies.find((t) => t.name === selected) ?? null;
}

function render() {
  for (const [name, pane] of Object.entries(panes)) {
    pane.classList.toggle('hidden', name !== tab);
  }
  const shown = visibleTrophies(doc.trophies, earned);
  if (tab === 'checklist') renderChecklist(panes.checklist, shown, earned, selected, select, toggle);
  else if (tab === 'roadmap') renderRoadmap(panes.roadmap, doc, earned, selected, select);
  else if (tab === 'missables') renderMissables(panes.missables, doc.trophies, earned, selected, select);
  renderDetail(detail, currentTrophy(), earned);
  showncount.textContent = tab === 'checklist'
    ? 'Showing ' + shown.length + ' of ' + doc.trophies.length + ' trophies'
    : '';
  updateProgress();
}

function select(name) {
  selected = name;
  if (tab !== 'checklist') { tab = 'checklist'; setActiveTab(); }
  render();
  document.getElementById('detailpane').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function toggle(name, on) {
  if (on) earned.add(name); else earned.delete(name);
  saveEarned(earned);
  render();
}

function setActiveTab() {
  for (const b of document.querySelectorAll('.tab')) {
    b.classList.toggle('active', b.dataset.tab === tab);
    b.setAttribute('aria-selected', String(b.dataset.tab === tab));
  }
}

for (const b of document.querySelectorAll('.tab')) {
  b.addEventListener('click', () => { tab = b.dataset.tab; sessionStorage.setItem(TAB_KEY, tab); setActiveTab(); render(); });
}

bindFilters(render);
spoilerBox.addEventListener('change', () => { filters.spoiler = spoilerBox.checked; saveSpoiler(spoilerBox.checked); render(); });

document.getElementById('exportbtn').addEventListener('click', () => exportProgress(earned));
document.getElementById('importinput').addEventListener('change', async (e) => {
  const file = e.target.files[0];
  if (!file) return;
  try {
    earned = await importProgress(file, earned, doc.trophies.map((t) => t.name));
    saveEarned(earned);
    render();
  } catch (err) {
    alert('Import failed: ' + err.message);
  } finally {
    e.target.value = '';
  }
});
document.getElementById('resetbtn').addEventListener('click', () => {
  if (!confirm('Clear all earned marks?')) return;
  earned = new Set();
  saveEarned(earned);
  render();
});

// Keyboard shortcuts: "/" focuses search, 1-4 switch tabs.
document.addEventListener('keydown', (e) => {
  if (e.target.matches('input, select, textarea')) return;
  if (e.key === '/') { e.preventDefault(); document.getElementById('search').focus(); }
  const n = Number(e.key);
  if (n >= 1 && n <= TAB_ORDER.length) {
    tab = TAB_ORDER[n - 1];
    sessionStorage.setItem(TAB_KEY, tab);
    setActiveTab();
    render();
  }
});

setActiveTab();
render();
```

### app/js/state.js (1985 bytes)

```js
// Persistent state: earned trophies, the spoiler setting, and progress export/import.
// Everything lives in localStorage so progress survives reloads; export/import round-trips
// through a JSON file and import only accepts names the official list holds.
const EARNED_KEY = 'gta6-trophies-earned-v2';
const SPOILER_KEY = 'gta6-spoiler-mode-v2';

export function loadEarned() {
  try {
    const list = JSON.parse(localStorage.getItem(EARNED_KEY) ?? '[]');
    if (!Array.isArray(list)) return new Set();
    return new Set(list.filter((n) => typeof n === 'string'));
  } catch {
    return new Set();
  }
}

export function saveEarned(earned) {
  localStorage.setItem(EARNED_KEY, JSON.stringify([...earned].sort()));
}

export function loadSpoiler() {
  return localStorage.getItem(SPOILER_KEY) === 'on';
}

export function saveSpoiler(on) {
  localStorage.setItem(SPOILER_KEY, on ? 'on' : 'off');
}

export function exportProgress(earned) {
  const payload = JSON.stringify({
    app: 'Leonida Legend — GTA VI trophy tracker',
    version: 2,
    exported: new Date().toISOString(),
    earned: [...earned].sort(),
  }, null, 2);
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([payload], { type: 'application/json' }));
  a.download = 'gta6-trophy-progress.json';
  a.click();
  URL.revokeObjectURL(a.href);
}

// Merges an exported file into what the tracker already holds, keeping only names on the
// official list; v1 files (a bare array or an {earned} object) import too.
export async function importProgress(file, current = new Set(), knownNames = null) {
  const data = JSON.parse(await file.text());
  const list = Array.isArray(data) ? data : data.earned;
  if (!Array.isArray(list)) throw new Error('not a progress file');
  const merged = new Set(current);
  for (const name of list) {
    if (typeof name !== 'string') continue;
    if (knownNames && !knownNames.includes(name)) continue;
    merged.add(name);
  }
  return merged;
}
```

### app/js/filters.js (1946 bytes)

```js
// Filter state and matching: text search (quote-normalised), kind, grade, missable-only,
// hide-earned, and spoiler mode, which hides story trophies' names and guides until earned.
export const filters = { search: '', kind: 'all', grade: 'all', missableOnly: false, hideEarned: false, spoiler: false };

// Curly quotes and asterisks off so a search for "ass drug" or "ts ass" finds the
// asterisked trophy without typing its exact punctuation.
function normalize(text) {
  return text.toLowerCase().replace(/["’‘“”*]/g, '');
}

export function bindFilters(onChange) {
  const q = document.getElementById('search');
  q.addEventListener('input', () => { filters.search = normalize(q.value); onChange(); });
  for (const [id, key] of [['kindfilter', 'kind'], ['gradefilter', 'grade']]) {
    const el = document.getElementById(id);
    el.addEventListener('change', () => { filters[key] = el.value; onChange(); });
  }
  for (const [id, key] of [['missablefilter', 'missableOnly'], ['hideearned', 'hideEarned'], ['spoiler', 'spoiler']]) {
    const el = document.getElementById(id);
    el.addEventListener('change', () => { filters[key] = el.checked; onChange(); });
  }
}

export function visibleTrophies(trophies, earned) {
  return trophies.filter((t) => {
    if (filters.kind !== 'all' && t.kind !== filters.kind) return false;
    if (filters.grade !== 'all' && t.grade !== filters.grade) return false;
    if (filters.missableOnly && !t.missable) return false;
    if (filters.hideEarned && earned.has(t.name)) return false;
    if (filters.search) {
      const hay = normalize(t.name + ' ' + t.description + ' ' + t.kind + ' ' + t.guide);
      if (!hay.includes(filters.search)) return false;
    }
    return true;
  });
}

// Spoiler mode hides the name and description of story trophies until they are earned.
export function isSpoiled(t, earned) {
  return filters.spoiler && t.kind === 'story' && !earned.has(t.name);
}
```

### app/js/checklist.js (2617 bytes)

```js
// The checklist: one card per trophy with its checkbox, grade badge, kind and missable
// flags, and keyboard access (every card is a button-like article; Enter opens its guide).
import { isSpoiled } from './filters.js';

function gradeRow(t) {
  const row = document.createElement('div');
  row.className = 'trow1';
  const name = document.createElement('p');
  name.className = 'tname';
  name.textContent = t.name;
  row.append(name);
  const grade = document.createElement('span');
  grade.className = 'badge ' + t.grade;
  grade.textContent = t.grade;
  row.append(grade);
  if (t.missable) {
    const m = document.createElement('span');
    m.className = 'badge missable';
    m.textContent = 'missable';
    row.append(m);
  }
  const kind = document.createElement('span');
  kind.className = 'badge kind';
  kind.textContent = t.kind;
  row.append(kind);
  return row;
}

function descriptionLine(t) {
  const desc = document.createElement('p');
  desc.className = 'tdesc';
  desc.textContent = t.description + (t.count ? ' (' + t.count + ')' : '');
  return desc;
}

function card(t, earned, selected, onSelect, onToggle) {
  const card = document.createElement('article');
  card.className = 'tcard' + (earned.has(t.name) ? ' earned' : '') + (selected === t.name ? ' selected' : '');
  card.tabIndex = 0;
  card.setAttribute('role', 'button');
  card.setAttribute('aria-label', t.name + (earned.has(t.name) ? ' (earned)' : ''));
  const box = document.createElement('input');
  box.type = 'checkbox';
  box.checked = earned.has(t.name);
  box.setAttribute('aria-label', 'Mark ' + t.name + ' earned');
  box.addEventListener('click', (e) => e.stopPropagation());
  box.addEventListener('change', () => onToggle(t.name, box.checked));
  const meta = document.createElement('div');
  meta.className = 'tmeta';
  meta.append(gradeRow(t), descriptionLine(t));
  card.append(box, meta);
  if (isSpoiled(t, earned)) card.classList.add('spoiled');
  card.addEventListener('click', () => onSelect(t.name));
  card.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onSelect(t.name); }
  });
  return card;
}

export function renderChecklist(container, trophies, earned, selected, onSelect, onToggle) {
  container.replaceChildren();
  for (const t of trophies) container.append(card(t, earned, selected, onSelect, onToggle));
  if (!trophies.length) {
    const p = document.createElement('p');
    p.className = 'stageblurb';
    p.textContent = 'No trophies match the current filters — clear the search or pick another kind.';
    container.append(p);
  }
}
```

### app/js/detail.js (3422 bytes)

```js
// The detail pane: official name/description/grade, the cited guide, steps, structured
// sources (each trophy carries its own list in data/trophies.json) and the missable note.
import { isSpoiled } from './filters.js';

const FALLBACK_SOURCES = [
  { name: 'Official trophy description (PlayStation), as listed by Exophase and PSNProfiles' },
];

function sourceLine(t) {
  const src = document.createElement('div');
  src.className = 'source';
  const title = document.createElement('h3');
  title.textContent = 'Sources';
  const list = document.createElement('ul');
  for (const s of t.sources ?? FALLBACK_SOURCES) {
    const li = document.createElement('li');
    if (s.url) {
      const a = document.createElement('a');
      a.href = s.url;
      a.textContent = s.name;
      a.rel = 'noopener';
      li.append(a);
    } else {
      li.textContent = s.name;
    }
    list.append(li);
  }
  const note = document.createElement('p');
  note.className = 'sourcenote';
  note.textContent = 'Every fact above is this entry’s own wording — no guide’s text is copied; a link opens only when you follow it.';
  src.append(title, list, note);
  return src;
}

export function renderDetail(container, t, earned) {
  container.replaceChildren();
  if (!t) {
    const hint = document.createElement('p');
    hint.className = 'hint';
    hint.textContent = 'Select a trophy to read its guide.';
    container.append(hint);
    return;
  }
  const spoiled = isSpoiled(t, earned);
  const h = document.createElement('h2');
  h.textContent = spoiled ? '??? (spoiler hidden — earn it first)' : t.name;
  const badges = document.createElement('div');
  badges.className = 'trow1';
  const grade = document.createElement('span');
  grade.className = 'badge ' + t.grade;
  grade.textContent = t.grade + (t.count ? ' · ' + t.count : '');
  badges.append(grade);
  const kind = document.createElement('span');
  kind.className = 'badge kind';
  kind.textContent = t.kind;
  badges.append(kind);
  if (t.missable) {
    const m = document.createElement('span');
    m.className = 'badge missable';
    m.textContent = 'missable';
    badges.append(m);
  }
  const stage = document.createElement('p');
  stage.className = 'stageblurb';
  stage.textContent = 'Roadmap stage ' + t.roadmapStage;
  const official = document.createElement('blockquote');
  official.className = 'official';
  official.textContent = spoiled
    ? 'Official description hidden by spoiler mode.'
    : 'Official description: ' + t.description;
  const body = document.createElement('div');
  body.className = 'guidebody';
  body.textContent = spoiled
    ? 'This is a story trophy and spoiler mode is on. Its guide stays hidden until you mark it earned.'
    : t.guide;
  container.append(h, badges, stage, official, body);
  if (spoiled) return;
  if (t.steps && t.steps.length) {
    const sh = document.createElement('h3');
    sh.textContent = 'How to do it';
    const ol = document.createElement('ol');
    ol.className = 'steps';
    for (const s of t.steps) {
      const li = document.createElement('li');
      li.textContent = s;
      ol.append(li);
    }
    container.append(sh, ol);
  }
  if (t.missable && t.missableNote) {
    const note = document.createElement('div');
    note.className = 'missnote';
    note.textContent = 'Missable — ' + t.missableNote;
    container.append(note);
  }
  container.append(sourceLine(t));
}
```

### app/js/roadmap.js (3180 bytes)

```js
// The platinum roadmap: the suggested order, grouped by stage, each stage with a live
// progress count and every trophy card showing its first guide line. Built from the
// official descriptions: story chapters and named missions first, then side work,
// activities, collectibles, the economy, and the 100% cleanup.
export function renderRoadmap(container, doc, earned, selected, onSelect) {
  container.replaceChildren();
  const intro = document.createElement('p');
  intro.className = 'stageblurb';
  intro.textContent = 'Suggested order to the platinum, built from what each official description asks for: story first (chapters and named missions), then the stranger strands, then activities, collectibles and exploration, then the economy and one-off stunts, and finally the 100% cleanup. Each stage counts what you have already marked earned.';
  container.append(intro);
  const byStage = new Map();
  for (const t of doc.trophies) {
    const key = String(t.roadmapStage).split('.')[0];
    if (!byStage.has(key)) byStage.set(key, []);
    byStage.get(key).push(t);
  }
  for (const stage of doc.roadmap) {
    const group = byStage.get(String(stage.stage)) ?? [];
    const done = group.filter((t) => earned.has(t.name)).length;
    const head = document.createElement('h3');
    head.className = 'stagehead';
    head.textContent = 'Stage ' + stage.stage + ' — ' + stage.name;
    const count = document.createElement('span');
    count.className = 'badge kind stagecount' + (done === group.length ? ' complete' : '');
    count.textContent = done + ' / ' + group.length + ' earned';
    head.append(count);
    const blurb = document.createElement('p');
    blurb.className = 'stageblurb';
    blurb.textContent = stage.blurb;
    container.append(head, blurb);
    for (const t of group) {
      const card = document.createElement('article');
      card.className = 'tcard' + (earned.has(t.name) ? ' earned' : '') + (selected === t.name ? ' selected' : '');
      card.tabIndex = 0;
      card.setAttribute('role', 'button');
      card.addEventListener('click', () => onSelect(t.name));
      card.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onSelect(t.name); }
      });
      const meta = document.createElement('div');
      meta.className = 'tmeta';
      const row1 = document.createElement('div');
      row1.className = 'trow1';
      const name = document.createElement('p');
      name.className = 'tname';
      name.textContent = t.name;
      const grade = document.createElement('span');
      grade.className = 'badge ' + t.grade;
      grade.textContent = t.grade;
      row1.append(name, grade);
      if (t.missable) {
        const m = document.createElement('span');
        m.className = 'badge missable';
        m.textContent = 'missable';
        row1.append(m);
      }
      const line = document.createElement('p');
      line.className = 'tdesc';
      const first = t.guide.split('\n')[0];
      line.textContent = first.slice(0, 160) + (first.length > 160 ? '…' : '');
      meta.append(row1, line);
      card.append(meta);
      container.append(card);
    }
  }
}
